const input = $input.first().json;
const body = input.body || input;

// Support Calendly, Cal.com, or custom webhook
const meeting = {
  email: body.invitee?.email || body.attendees?.[0]?.email || body.email,
  name: body.invitee?.name || body.attendees?.[0]?.name || body.name,
  meeting_type: body.event_type?.name || body.eventType || body.meeting_type || 'discovery_call',
  scheduled_at: body.event?.start_time || body.startTime || body.scheduled_at,
  duration_minutes: body.event?.duration || body.duration || 30,
  meeting_url: body.event?.location?.join_url || body.meetingUrl || body.location,
  assigned_to: body.event?.event_memberships?.[0]?.user_name || body.organizer || body.assigned_to,
  notes: body.questions_and_answers?.map(q => `${q.question}: ${q.answer}`).join('\n') || body.notes || '',
  source: body.source || 'calendly',
  client_id: body.client_id
};

if (!meeting.email) {
  return [{ json: { error: true, message: 'Missing attendee email' } }];
}

return [{ json: meeting }];

const contact = $input.first().json;
const meeting = $node['Parse Meeting Data'].json;

const contactId = contact.id || null;
const isNewContact = !contactId;

return [{
  json: {
    ...meeting,
    contact_id: contactId,
    is_new_contact: isNewContact,
    contact_name: contact.first_name ? `${contact.first_name} ${contact.last_name}` : meeting.name,
    company: contact.company || '',
    lead_score: contact.lead_score || 0
  }
}];
